TRIGGER = "\nCREATE FUNCTION his_guard_assistant_evidence() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Assistant evidence cannot be deleted'; END IF;\n IF TG_TABLE_NAME='assistant_runs' THEN\n  IF (to_jsonb(NEW)-ARRAY['execution_state','review_state','provider','usage','measured_cost','error','lease_id','lease_expires_at','hold_until','started_at','completed_at']) IS DISTINCT FROM\n     (to_jsonb(OLD)-ARRAY['execution_state','review_state','provider','usage','measured_cost','error','lease_id','lease_expires_at','hold_until','started_at','completed_at']) THEN RAISE EXCEPTION 'Assistant source/request identity immutable'; END IF;\n  IF OLD.execution_state NOT IN ('queued','waiting_for_capacity','running') AND NEW.execution_state IS DISTINCT FROM OLD.execution_state THEN RAISE EXCEPTION 'Assistant completed attempt cannot restart'; END IF;\n ELSIF TG_TABLE_NAME='assistant_watches' THEN\n  IF (to_jsonb(NEW)-ARRAY['status','next_scan_at','last_source_digest','last_run_id','last_enqueued_at','auto_run_count']) IS DISTINCT FROM\n     (to_jsonb(OLD)-ARRAY['status','next_scan_at','last_source_digest','last_run_id','last_enqueued_at','auto_run_count']) THEN RAISE EXCEPTION 'Assistant watch identity immutable'; END IF;\n  IF NEW.auto_run_count<OLD.auto_run_count THEN RAISE EXCEPTION 'Watch count cannot regress'; END IF;\n ELSE RAISE EXCEPTION 'Assistant revisions decisions and receipts immutable';\n END IF;\n RETURN NEW;\nEND; $$\n"

def upgrade():
    for statement in DDL:
        op.execute(statement)
    op.execute(TRIGGER)
    for name in ('assistant_runs','assistant_revisions','assistant_decisions','assistant_effects','assistant_watches'):
        op.execute(f"CREATE TRIGGER assistant_evidence_guard BEFORE UPDATE OR DELETE ON {name} FOR EACH ROW EXECUTE FUNCTION his_guard_assistant_evidence()")

